/**
 * Method RPC client — typed function calls to backend methods.
 *
 * `createClient()` returns a Proxy where every property access creates
 * an async function that invokes the corresponding backend method via HTTP.
 * The method name matches the method's `export` field in `app.json`.
 *
 * ## How it works
 *
 * ```
 * api.submitVendorRequest({ name: 'Acme' })
 *   │
 *   ├─ Look up method ID: config.methods["submitVendorRequest"]
 *   │  → "submit-vendor-request"
 *   │
 *   ├─ POST {apiBaseUrl}/_internal/v2/apps/{appId}/methods/submit-vendor-request/invoke
 *   │  Authorization: Bearer {session token}
 *   │  Body: { input: { name: "Acme" } }
 *   │
 *   └─ Returns response.output (or throws on error)
 * ```
 *
 * The method registry (export name → method ID mapping) is embedded in
 * `window.__MINDSTUDIO__.methods` at page load time — no extra HTTP call
 * needed to discover methods.
 *
 * ## Streaming
 *
 * Methods can optionally stream LLM token output via SSE. Pass
 * `{ stream: true }` as the second argument along with an `onToken`
 * callback to receive incremental updates:
 *
 * ```ts
 * const result = await api.submitVendorRequest({ name: 'Acme' }, {
 *   stream: true,
 *   onToken: (text) => setResponseText(text),
 * });
 * ```
 *
 * **Important:** The `text` value passed to `onToken` is the accumulated
 * response so far (not a delta). Replace your display content each time —
 * do not append. See {@link InvokeOptions.onToken} for details.
 *
 * ## Type safety
 *
 * Since the frontend and backend live in the same project, you can import
 * types directly:
 *
 * ```ts
 * import type { SubmitVendorInput, SubmitVendorOutput }
 *   from '../../backend/src/submitVendorRequest';
 *
 * interface AppMethods {
 *   submitVendorRequest(input: SubmitVendorInput): Promise<SubmitVendorOutput>;
 *   getDashboard(): Promise<GetDashboardOutput>;
 * }
 *
 * const api = createClient<AppMethods>();
 * const result = await api.submitVendorRequest({ name: 'Acme' }); // fully typed
 * ```
 *
 * If no type parameter is provided, methods accept `any` input and return `any`.
 */
/**
 * Options for method invocation. Pass as the optional second argument to
 * any method on the client returned by {@link createClient}.
 *
 * When `stream` is `true`, the SDK sends `{ stream: true }` in the request
 * body and parses the response as an SSE (Server-Sent Events) stream.
 * Three event types are handled:
 *
 * | SSE `type` | Payload field | SDK action |
 * |------------|---------------|------------|
 * | `token`    | `text`        | Calls {@link onToken} with accumulated text |
 * | `error`    | `error`       | Calls {@link onStreamError} with the message |
 * | `done`     | `output`      | Captures as the method's return value |
 *
 * The method's `Promise` resolves with the final `output` from the `done`
 * event — the same shape you'd get without streaming.
 */
interface InvokeOptions {
    /**
     * Enable SSE streaming for LLM token output.
     *
     * When `true`, the request body includes `{ stream: true }` and the
     * response is parsed as an SSE stream instead of a single JSON payload.
     * The method still returns a `Promise` that resolves with the final
     * output once the stream completes.
     *
     * @default false
     */
    stream?: boolean;
    /**
     * Called with the accumulated response text each time a new token arrives.
     *
     * **Important:** `text` is the full response so far, not a delta/chunk.
     * Your frontend should **replace** (not append to) its display content
     * with this value each time the callback fires.
     *
     * This design avoids edge cases where the platform sanitizes or
     * reformats JSON mid-stream, causing earlier portions of the text to
     * change between tokens.
     *
     * @example
     * ```ts
     * const result = await api.generate({ prompt: 'Hello' }, {
     *   stream: true,
     *   onToken: (text) => {
     *     // Replace — do NOT append
     *     responseElement.textContent = text;
     *   },
     * });
     * ```
     */
    onToken?: (text: string) => void;
    /**
     * Called if a stream-level error occurs.
     *
     * Stream errors are non-fatal at the protocol level — the method may
     * still complete and resolve with a final output. Use this callback for
     * logging or showing a transient warning, not for control flow.
     *
     * If the stream ends without a `done` event, the method rejects with a
     * `MindStudioInterfaceError` (code `stream_incomplete`) regardless of
     * whether `onStreamError` was provided.
     */
    onStreamError?: (error: string) => void;
}
/**
 * Default client type when no generic parameter is provided.
 * Every property returns an async function accepting optional input
 * and optional {@link InvokeOptions} for streaming.
 */
type DefaultMethodClient = Record<string, (input?: Record<string, unknown>, options?: InvokeOptions) => Promise<unknown>>;
/**
 * Create a typed RPC client for calling backend methods.
 *
 * @typeParam T - Optional interface mapping method names to their signatures.
 *   If omitted, all methods accept `any` and return `Promise<any>`.
 *
 * @returns A Proxy object where each property is an async function that
 *   invokes the corresponding backend method.
 *
 * @example
 * ```ts
 * import { createClient } from '@mindstudio-ai/interface';
 *
 * const api = createClient();
 *
 * // Each method maps to a backend method export
 * const result = await api.submitVendorRequest({ name: 'Acme' });
 * const dashboard = await api.getDashboard();
 *
 * // Stream LLM output — onToken receives accumulated text (replace, don't append)
 * const streamed = await api.submitVendorRequest({ name: 'Acme' }, {
 *   stream: true,
 *   onToken: (text) => setResponseText(text),
 * });
 * // `streamed` is the same final output you'd get without streaming
 * ```
 */
declare function createClient<T = DefaultMethodClient>(): T;

/**
 * Type definitions for the @mindstudio-ai/interface SDK.
 *
 * These types describe the bootstrap globals injected by the platform,
 * the user context, and options for platform actions.
 */
/**
 * Bootstrap configuration injected into the page by the MindStudio
 * platform before the app's JavaScript runs.
 *
 * Available at `window.__MINDSTUDIO__`. The SDK reads this automatically —
 * app code should use `createClient()`, `auth`, and `platform` instead
 * of accessing this directly.
 *
 * Injection mechanism: The Cloudflare Worker on `*.static.mscdn.ai`
 * intercepts requests for `index.html`, injects a `<script>` tag with
 * the session context, and returns the modified HTML.
 */
interface BootstrapConfig {
    /** Short-lived session token scoped to this app + user. */
    token: string;
    /** App ID. */
    appId: string;
    /** Current release ID. */
    releaseId: string;
    /** API base URL (e.g. "https://api.mindstudio.ai"). */
    apiBaseUrl: string;
    /** Resolved user fragment — display info for the current user. */
    user: BootstrapUser;
    /**
     * Method registry mapping export names to method IDs.
     * Embedded at injection time from the release manifest.
     *
     * @example
     * ```
     * { "submitVendorRequest": "submit-vendor-request", "getDashboard": "get-dashboard" }
     * ```
     */
    methods: Record<string, string>;
}
/**
 * Resolved user fragment. Includes display info so apps can render
 * personalized UI immediately without an extra API call.
 */
interface BootstrapUser {
    /** User ID (UUID). */
    id: string;
    /** Display name. */
    name: string;
    /** Email address. */
    email: string;
    /** Profile picture URL, if set. */
    profilePictureUrl?: string;
}
/**
 * Options for `platform.requestFile()`.
 */
interface RequestFileOptions {
    /** Filter the file picker by type. */
    type?: 'image' | 'video' | 'audio' | 'document';
}

/**
 * Platform actions — file picker and uploads via the MindStudio host.
 *
 * These are actions that require interaction with the MindStudio platform
 * (the parent window that hosts the iframe). The file picker uses
 * postMessage to communicate with the host; file uploads go directly
 * to the API.
 *
 * ## `platform.requestFile(options?)`
 *
 * Opens the MindStudio asset library / file picker. The user can upload
 * a new file or choose from their existing assets. Returns the CDN URL.
 *
 * Uses the postMessage callback token pattern:
 * 1. SDK generates a unique callback token
 * 2. Sends `{ action: 'requestFile', type?, callbackToken }` to parent
 * 3. Parent opens the asset library modal
 * 4. User picks a file → parent sends `{ action: 'callback', callbackToken, result: { url } }`
 * 5. SDK resolves the promise with the URL
 *
 * ## `platform.uploadFile(file)`
 *
 * Uploads a file directly to the MindStudio CDN without opening a picker.
 * Uses a direct HTTP POST with the session token — no postMessage needed.
 *
 * @example
 * ```ts
 * import { platform } from '@mindstudio-ai/interface';
 *
 * // Open the file picker
 * const url = await platform.requestFile({ type: 'image' });
 *
 * // Upload directly
 * const file = document.querySelector('input[type=file]').files[0];
 * const uploadedUrl = await platform.uploadFile(file);
 * ```
 */

/**
 * The platform namespace — file picker and upload actions.
 */
declare const platform: {
    /**
     * Open the MindStudio asset library / file picker.
     *
     * Returns the CDN URL of the selected or uploaded file.
     * Throws if the user cancels the picker.
     *
     * @param options - Optional filter by file type
     * @returns CDN URL of the selected file
     *
     * @example
     * ```ts
     * const imageUrl = await platform.requestFile({ type: 'image' });
     * const anyFile = await platform.requestFile();
     * ```
     */
    requestFile(options?: RequestFileOptions): Promise<string>;
    /**
     * Upload a file directly to the MindStudio CDN.
     *
     * Does not open a picker — use this when you already have a File
     * object (e.g. from a drag-and-drop or a custom file input).
     *
     * @param file - The File to upload
     * @returns CDN URL of the uploaded file
     *
     * @example
     * ```ts
     * const file = inputElement.files[0];
     * const url = await platform.uploadFile(file);
     * ```
     */
    uploadFile(file: File): Promise<string>;
};

/**
 * Auth context — current user's identity for display purposes.
 *
 * Provides synchronous access to the current user's name, email, and
 * profile picture. Hydrated from the bootstrap globals injected by the
 * platform — no HTTP call needed.
 *
 * This is for **display only**. Role checking, permission enforcement,
 * and user lookups for other users are backend concerns — the frontend
 * calls backend methods that handle those via `@mindstudio-ai/agent`'s
 * `auth` namespace.
 *
 * @example
 * ```ts
 * import { auth } from '@mindstudio-ai/interface';
 *
 * return (
 *   <div>
 *     <p>Welcome, {auth.name}</p>
 *     <img src={auth.profilePictureUrl} />
 *   </div>
 * );
 * ```
 */
/**
 * User identity context. All properties are read-only and synchronous.
 */
interface AuthContext {
    /** Current user's ID (UUID). */
    readonly userId: string;
    /** Current user's display name. */
    readonly name: string;
    /** Current user's email address. */
    readonly email: string;
    /** Current user's profile picture URL, or null if not set. */
    readonly profilePictureUrl: string | null;
}
/**
 * Lazy auth proxy — reads from bootstrap globals on first property access.
 *
 * Using a Proxy lets us export `auth` as a module-level constant while
 * deferring the `getConfig()` call until the first property is accessed.
 * This avoids throwing during import if the page hasn't finished loading
 * the bootstrap script yet.
 */
declare const auth: AuthContext;

/**
 * Error class for the @mindstudio-ai/interface SDK.
 *
 * Thrown by `createClient()` method calls on HTTP errors, by `platform`
 * actions on failures, and by the config reader when bootstrap globals
 * are missing.
 */
declare class MindStudioInterfaceError extends Error {
    /** Machine-readable error code (e.g. 'method_not_found', 'not_initialized'). */
    readonly code: string;
    /** HTTP status code, when the error originated from an API response. */
    readonly status?: number;
    constructor(message: string, code: string, status?: number);
}

export { type AuthContext, type BootstrapConfig, type BootstrapUser, type InvokeOptions, MindStudioInterfaceError, type RequestFileOptions, auth, createClient, platform };
